/**
 * Compatibility content keeps the original three-module/six-unit envelope.
 * The v2 limits are authoring safety ceilings, not clinical tiers, encounter
 * difficulty labels, point values, or targets that generation must exhaust.
 */
export const LEGACY_PATIENT_OPTIONAL_FEATURE_MAX_COST = 3;
export const LEGACY_PATIENT_OPTIONAL_FEATURE_MAX_BUDGET = 6;
export const LEGACY_PATIENT_OPTIONAL_FEATURE_MAX_SELECTED_MODULES = 3;
export const PATIENT_OPTIONAL_FEATURE_MAX_COST = 12;
export const PATIENT_OPTIONAL_FEATURE_MAX_BUDGET = 96;
export const PATIENT_OPTIONAL_FEATURE_MAX_SELECTED_MODULES = 24;
export const PATIENT_OPTIONAL_FEATURE_MAX_SELECTION_ORDINAL =
  PATIENT_OPTIONAL_FEATURE_MAX_SELECTED_MODULES - 1;
export const PATIENT_COMPLEXITY_MAX_BASELINE_UNITS = 64;

export const ComplexityContributionSchema = z
  .object({
    id: StableIdSchema,
    label: z.string().min(1).max(180),
    dimension: ComplexityDimensionSchema,
    weight: z.number().int().min(1).max(5),
    review: UnreviewedClinicalRuleSchema,
  })
  .strict();
export type ComplexityContribution = z.infer<typeof ComplexityContributionSchema>;

export const DiagnosisSeverityConstraintsSchema = z
  .object({
    criteriaSetId: StableIdSchema.nullable(),
    minimumPositiveCriteria: z.number().int().nonnegative().nullable(),
    maximumPositiveCriteria: z.number().int().nonnegative().nullable(),
    requiredCriterionIds: z.array(StableIdSchema),
    forbiddenCriterionIds: z.array(StableIdSchema),
    minimumFunctionalImpairment: z.enum(['none', 'mild', 'moderate', 'severe']).nullable(),
  })
  .strict()
  .superRefine((constraints, context) => {
    if (
      constraints.minimumPositiveCriteria !== null &&
      constraints.maximumPositiveCriteria !== null &&
      constraints.minimumPositiveCriteria > constraints.maximumPositiveCriteria
    ) {
      context.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['maximumPositiveCriteria'],
        message: 'A severity range minimum must not exceed its maximum.',
      });
    }
    if (
      constraints.requiredCriterionIds.some((id) => constraints.forbiddenCriterionIds.includes(id))
    ) {
      context.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['requiredCriterionIds'],
        message: 'A severity criterion cannot be both required and forbidden.',
      });
    }
  });
export type DiagnosisSeverityConstraints = z.infer<typeof DiagnosisSeverityConstraintsSchema>;

export const DiagnosisSeverityLevelSchema = z
  .object({
    id: StableIdSchema,
    label: z.string().min(1).max(120),
    rank: z.number().int().nonnegative(),
    generationStatus: z.enum(['disabled_pending_source', 'enabled']),
    constraints: DiagnosisSeverityConstraintsSchema,
    addedClinicalTagIds: z.array(StableIdSchema),
    rules: z.array(DiagnosisRecommendationRuleSchema),
    complexityContributions: z.array(ComplexityContributionSchema),
    review: UnreviewedClinicalRuleSchema,
  })
  .strict()
  .superRefine((level, context) => {
    const constraints = level.constraints;
    const hasOperationalConstraint =
      constraints.criteriaSetId !== null ||
      constraints.minimumPositiveCriteria !== null ||
      constraints.maximumPositiveCriteria !== null ||
      constraints.requiredCriterionIds.length > 0 ||
      constraints.forbiddenCriterionIds.length > 0 ||
      constraints.minimumFunctionalImpairment !== null;
    if (level.generationStatus === 'enabled' && !hasOperationalConstraint) {
      context.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['constraints'],
        message: 'An enabled severity level requires at least one operational constraint.',
      });
    }
  });
export type DiagnosisSeverityLevel = z.infer<typeof DiagnosisSeverityLevelSchema>;

export const DiagnosisSeverityDerivationInputSchema = z.enum([
  'symptom_severity',
  'condition_attributed_functional_impairment',
]);
export type DiagnosisSeverityDerivationInput = z.infer<
  typeof DiagnosisSeverityDerivationInputSchema
>;

/**
 * The first reviewed derivation shape keeps both inputs independently
 * auditable and names only their qualitative combination. It does not define
 * how either input is generated or where mild/moderate/severe boundaries lie.
 */
export const DiagnosisSeverityDerivationPolicySchema = z
  .object({
    id: StableIdSchema,
    strategy: z.literal('highest_qualitative_level'),
    inputDimensions: z.array(DiagnosisSeverityDerivationInputSchema).length(2),
    review: UnreviewedClinicalRuleSchema,
  })
  .strict()
  .superRefine((policy, context) => {
    const expected = new Set(DiagnosisSeverityDerivationInputSchema.options);
    const actual = new Set(policy.inputDimensions);
    if (
      actual.size !== expected.size ||
      [...expected].some((dimension) => !actual.has(dimension))
    ) {
      context.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['inputDimensions'],
        message:
          'The highest-qualitative-level policy requires separate symptom-severity and condition-attributed-functional-impairment inputs.',
      });
    }
  });
export type DiagnosisSeverityDerivationPolicy = z.infer<
  typeof DiagnosisSeverityDerivationPolicySchema
>;

