export const FindingSourceReportProjectionModifierSchema = z
  .object({
    moduleRef: z.lazy(() => CatalogInstanceVersionedReferenceSchema),
    moduleFingerprint: z.lazy(() => OptionalFeatureBudgetFingerprintSchema),
    optionalFeatureBindingId: StableIdSchema,
    selectedModuleId: StableIdSchema,
    projectionRef: z.lazy(() => CatalogInstanceVersionedReferenceSchema),
  })
  .strict();
export type FindingSourceReportProjectionModifier = z.infer<
  typeof FindingSourceReportProjectionModifierSchema
>;

/**
 * One slot governs one exact hidden-finding-state-to-patient-report mapping.
 * A symptom item may own separate slots for its present and absent hidden
 * states; only the slot whose source predicate matches can emit a response.
 */
export const FindingSourceReportProjectionSlotSchema = z
  .object({
    schemaVersion: SchemaVersionSchema,
    id: StableIdSchema,
    source: z
      .object({
        kind: z.literal('patient_report'),
        sourceInstanceId: StableIdSchema,
      })
      .strict(),
    timeScopeId: StableIdSchema,
    claimOriginId: StableIdSchema,
    dependencyGroupIds: z.array(StableIdSchema).max(64),
    baseProjectionRef: z.lazy(() => CatalogInstanceVersionedReferenceSchema),
    modifiers: z.array(FindingSourceReportProjectionModifierSchema).min(1).max(32),
  })
  .strict()
  .superRefine((slot, context) => {
    const moduleKeys = slot.modifiers.map(
      (modifier) => `${modifier.moduleRef.id}\u0000${modifier.moduleRef.contentVersion}`,
    );
    if (
      new Set(slot.dependencyGroupIds).size !== slot.dependencyGroupIds.length ||
      new Set(moduleKeys).size !== moduleKeys.length
    ) {
      context.addIssue({
        code: z.ZodIssueCode.custom,
        message:
          'A finding source-report slot requires unique dependency groups and one exact modifier per optional-module identity.',
      });
    }
  });
export type FindingSourceReportProjectionSlot = z.infer<
  typeof FindingSourceReportProjectionSlotSchema
>;

/**
 * D-258 is a post-truth projection policy, not another selector. It embeds the
 * one complete D-201 artifact and chooses only between reviewed D-193
 * projections. The hidden finding, original complexity draw, and cost remain
 * unchanged.
 */
export const FindingSourceReportProjectionPolicySchema = z
  .object({
    schemaVersion: SchemaVersionSchema,
    contentVersion: ContentVersionSchema,
    id: StableIdSchema,
    modelVersion: z.literal('finding-source-report-projection.v1'),
    optionalFeatureArtifact: z.lazy(() => OptionalFeatureBudgetSelectionArtifactSchema),
    slots: z.array(FindingSourceReportProjectionSlotSchema).min(1).max(256),
    developerOpinionIds: z.array(StableIdSchema),
    lifecycle: ContentLifecycleSchema,
    review: ClinicalRuleReviewSchema,
  })
  .strict()
  .superRefine((policy, context) => {
    const slotIds = policy.slots.map((slot) => slot.id);
    const projectionKeys = policy.slots.flatMap((slot) => [
      `${slot.baseProjectionRef.id}\u0000${slot.baseProjectionRef.contentVersion}`,
      ...slot.modifiers.map(
        (modifier) => `${modifier.projectionRef.id}\u0000${modifier.projectionRef.contentVersion}`,
      ),
    ]);
    const definitionsById = new Map(
      policy.optionalFeatureArtifact.selectionRequest.moduleDefinitions.map((definition) => [
        definition.id,
        definition,
      ]),
    );
    const bindingsById = new Map(
      policy.optionalFeatureArtifact.selectionRequest.profile.candidateBindings.map((binding) => [
        binding.id,
        binding,
      ]),
    );
    const evaluationsByDefinitionId = new Map(
      policy.optionalFeatureArtifact.candidateEvaluations.map((evaluation) => [
        evaluation.moduleRef.id,
        evaluation,
      ]),
    );
    const incompatibilityPairs = new Set(
      policy.optionalFeatureArtifact.selectionRequest.profile.incompatibilities.map(
        (incompatibility) =>
          `${incompatibility.leftModuleId}\u0000${incompatibility.rightModuleId}`,
      ),
    );
    if (
      new Set(slotIds).size !== slotIds.length ||
      new Set(projectionKeys).size !== projectionKeys.length ||
      new Set(policy.developerOpinionIds).size !== policy.developerOpinionIds.length ||
      policy.lifecycle !== 'approved' ||
      policy.review.status !== 'approved' ||
      (policy.review.sourceUseNoteIds.length === 0 && policy.developerOpinionIds.length === 0)
    ) {
      context.addIssue({
        code: z.ZodIssueCode.custom,
        message:
          'An executable finding source-report policy requires unique slots/projections, approved review, and formal contribution or Developer-opinion provenance.',
      });
    }
    policy.slots.forEach((slot, slotIndex) => {
      const selectedModifiers = slot.modifiers.filter(
        (modifier) =>
          evaluationsByDefinitionId.get(modifier.moduleRef.id)?.disposition === 'selected',
      );
      if (selectedModifiers.length > 1) {
        context.addIssue({
          code: z.ZodIssueCode.custom,
          path: ['slots', slotIndex, 'modifiers'],
          message:
            'At most one D-201-selected source-report modifier may control one exact finding-report slot.',
        });
      }
      for (let leftIndex = 0; leftIndex < slot.modifiers.length; leftIndex += 1) {
        for (let rightIndex = leftIndex + 1; rightIndex < slot.modifiers.length; rightIndex += 1) {
          if (
            policy.optionalFeatureArtifact.selectionRequest.template.complexityProfile
              .maximumSelectedModules <= 1
          ) {
            continue;
          }
          const pair = [
            slot.modifiers[leftIndex]!.moduleRef.id,
            slot.modifiers[rightIndex]!.moduleRef.id,
          ].sort();
          if (!incompatibilityPairs.has(`${pair[0]}\u0000${pair[1]}`)) {
            context.addIssue({
              code: z.ZodIssueCode.custom,
              path: ['slots', slotIndex, 'modifiers'],
              message:
                'Finding-report modifiers sharing one slot must already be mutually incompatible in D-201.',
            });
          }
        }
      }
      slot.modifiers.forEach((modifier, modifierIndex) => {
        const definition = definitionsById.get(modifier.moduleRef.id);
        const binding = bindingsById.get(modifier.optionalFeatureBindingId);
        const evaluation = evaluationsByDefinitionId.get(modifier.moduleRef.id);
        if (
          definition?.moduleKind !== 'source_report' ||
          definition.contentVersion !== modifier.moduleRef.contentVersion ||
          evaluation?.moduleFingerprint !== modifier.moduleFingerprint ||
          evaluation.bindingId !== modifier.optionalFeatureBindingId ||
          evaluation.moduleSnapshot.id !== modifier.selectedModuleId ||
          binding?.moduleRef.id !== modifier.moduleRef.id ||
          binding.moduleRef.contentVersion !== modifier.moduleRef.contentVersion ||
          binding.moduleFingerprint !== modifier.moduleFingerprint ||
          binding.selectedModuleId !== modifier.selectedModuleId
        ) {
          context.addIssue({
            code: z.ZodIssueCode.custom,
            path: ['slots', slotIndex, 'modifiers', modifierIndex],
            message:
              'Each finding-report modifier must pin one exact source_report definition, D-201 binding, selected-record identity, and candidate evaluation.',
          });
        }
      });
    });
  });
export type FindingSourceReportProjectionPolicy = z.infer<
  typeof FindingSourceReportProjectionPolicySchema
>;

export const FindingProjectionPropositionDefinitionReferenceSchema = z
  .object({
    id: StableIdSchema,
    contentVersion: ContentVersionSchema,
  })
  .strict();
export type FindingProjectionPropositionDefinitionReference = z.infer<
  typeof FindingProjectionPropositionDefinitionReferenceSchema
>;

export const SharedFindingCompileRequestSchema = z
  .object({
    schemaVersion: SchemaVersionSchema,
    id: StableIdSchema,
    patientStateId: StableIdSchema,
    seed: z.string().min(1).max(512),
    findingDefinitions: z.array(FindingDefinitionSchema).min(1),
    candidates: z.array(FindingResolutionCandidateSchema).min(1),
    propositionState: ResolvedPatientPropositionStateSchema,
    propositionDefinitions: z.array(FindingProjectionPropositionDefinitionReferenceSchema),
    projections: z.array(FindingRevealProjectionSchema),
    expressionBanks: z.array(FindingExpressionBankSchema),
    projectionHorizon: FindingProjectionHorizonSchema,
    findingSourceReportProjectionPolicy: z
      .lazy(() => FindingSourceReportProjectionPolicySchema)
      .optional(),
  })
  .strict()
  .superRefine((request, context) => {
    for (const [path, ids] of [
      ['findingDefinitions', request.findingDefinitions.map((definition) => definition.id)],
      ['candidates', request.candidates.map((candidate) => candidate.id)],
      ['propositionDefinitions', request.propositionDefinitions.map((definition) => definition.id)],
      ['projections', request.projections.map((projection) => projection.id)],
      ['expressionBanks', request.expressionBanks.map((bank) => bank.id)],
    ] as const) {
      if (new Set(ids).size !== ids.length) {
        context.addIssue({
          code: z.ZodIssueCode.custom,
          path: [path],
          message: `Shared-finding compiler ${path} IDs must be unique.`,
        });
      }
    }
    const contributionIds = request.candidates.flatMap((candidate) =>
      candidate.contributions.map((contribution) => contribution.id),
    );
    if (new Set(contributionIds).size !== contributionIds.length) {
      context.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['candidates'],
        message: 'Finding contribution IDs must be globally unique within one compilation.',
      });
    }
    const policy = request.findingSourceReportProjectionPolicy;
    if (policy !== undefined) {
      const projectionsByKey = new Map(
        request.projections.map((projection) => [
          `${projection.id}\u0000${projection.contentVersion}`,
          projection,
        ]),
      );
      if (
        policy.optionalFeatureArtifact.seed !== request.seed ||
        policy.optionalFeatureArtifact.selectionRequest.seed !== request.seed
      ) {
        context.addIssue({
          code: z.ZodIssueCode.custom,
          path: ['findingSourceReportProjectionPolicy', 'optionalFeatureArtifact', 'seed'],
          message:
            'A finding source-report policy must reuse the shared patient-generation seed retained by D-201.',
        });
      }
      policy.slots.forEach((slot, slotIndex) => {
        const base = projectionsByKey.get(
          `${slot.baseProjectionRef.id}\u0000${slot.baseProjectionRef.contentVersion}`,
        );
        if (base === undefined || base.review.status !== 'approved') {
          context.addIssue({
            code: z.ZodIssueCode.custom,
            path: ['findingSourceReportProjectionPolicy', 'slots', slotIndex, 'baseProjectionRef'],
            message:
              'A finding source-report slot requires one included, exact, approved base projection.',
          });
          return;
        }
        slot.modifiers.forEach((modifier, modifierIndex) => {
          const alternative = projectionsByKey.get(
            `${modifier.projectionRef.id}\u0000${modifier.projectionRef.contentVersion}`,
          );
          if (
            alternative === undefined ||
            alternative.review.status !== 'approved' ||
            base.sourceMatch !== alternative.sourceMatch ||
            JSON.stringify(base.sourceBindings) !== JSON.stringify(alternative.sourceBindings) ||
            JSON.stringify(base.target) !== JSON.stringify(alternative.target)
          ) {
            context.addIssue({
              code: z.ZodIssueCode.custom,
              path: [
                'findingSourceReportProjectionPolicy',
                'slots',
                slotIndex,
                'modifiers',
                modifierIndex,
                'projectionRef',
              ],
              message:
                'A finding-report modifier must name an included approved projection with the exact same hidden source predicate and target as its base.',
            });
          }
        });
      });
    }
  });
export type SharedFindingCompileRequest = z.infer<typeof SharedFindingCompileRequestSchema>;

export const FindingCandidateDispositionSchema = z.enum([
  'applied',
  'compatible_not_decisive',
  'superseded_by_override',
  'required_value_prevailed',
  'higher_priority_candidate_prevailed',
  'no_opinion',
  'not_reviewed',
]);
export type FindingCandidateDisposition = z.infer<typeof FindingCandidateDispositionSchema>;

export const FindingCandidateEvaluationSchema = z
  .object({
    candidateId: StableIdSchema,
    findingDefinitionId: StableIdSchema,
    kind: FindingResolutionCandidateKindSchema,
    proposedValue: ResolvedCanonicalFindingValueSchema.nullable(),
    uncertainty: z.enum(['none', 'reported_uncertain', 'conflicting_sources']).nullable(),
    contributionIds: z.array(StableIdSchema).min(1),
    resolution: PatientStateResolutionTraceSchema.nullable(),
    review: ClinicalRuleReviewSchema,
    disposition: FindingCandidateDispositionSchema,
  })
  .strict()
  .superRefine((evaluation, context) => {
    const reviewed = evaluation.review.status === 'approved';
    if (
      (reviewed && evaluation.disposition === 'not_reviewed') ||
      (!reviewed && evaluation.disposition !== 'not_reviewed')
    ) {
      context.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['disposition'],
        message: 'Candidate review status and evaluation disposition must agree.',
      });
    }
    if (evaluation.kind === 'no_opinion') {
      if (
        evaluation.proposedValue !== null ||
        evaluation.uncertainty !== null ||
        evaluation.resolution !== null ||
        (evaluation.disposition !== 'no_opinion' && evaluation.disposition !== 'not_reviewed')
      ) {
        context.addIssue({
          code: z.ZodIssueCode.custom,
          message: 'A no-opinion evaluation must remain value-free and inert.',
        });
      }
      return;
    }
    if (
      evaluation.proposedValue === null ||
      evaluation.uncertainty === null ||
      evaluation.resolution === null ||
      evaluation.disposition === 'no_opinion'
    ) {
      context.addIssue({
        code: z.ZodIssueCode.custom,
        message:
          'A value-bearing candidate evaluation requires its frozen value, uncertainty, resolution, and value-bearing disposition.',
      });
    }
  });
export type FindingCandidateEvaluation = z.infer<typeof FindingCandidateEvaluationSchema>;

export const SharedFindingCompilationDiagnosticSchema = z
  .object({
    code: z.enum(['candidate_not_approved', 'projection_not_approved']),
    contentIds: z.array(StableIdSchema).min(1),
    message: z.string().min(1).max(500),
  })
  .strict();
export type SharedFindingCompilationDiagnostic = z.infer<
  typeof SharedFindingCompilationDiagnosticSchema
>;

export const CompiledSharedFindingSetSchema = z
  .object({
    schemaVersion: SchemaVersionSchema,
    id: StableIdSchema,
    compilerVersion: ContentVersionSchema,
    requestId: StableIdSchema,
    patientStateId: StableIdSchema,
    projectionHorizonId: StableIdSchema,
    projectionHorizonFingerprint: FindingCompilerFingerprintSchema,
    inputFingerprint: FindingCompilerFingerprintSchema,
    payloadFingerprint: FindingCompilerFingerprintSchema,
    findings: z.array(ResolvedCanonicalFindingSchema).min(1),
    candidateEvaluations: z.array(FindingCandidateEvaluationSchema).min(1),
    projections: z.array(ResolvedFindingProjectionSchema),
    diagnostics: z.array(SharedFindingCompilationDiagnosticSchema),
  })
  .strict()
  .superRefine((compiled, context) => {
    for (const [path, ids] of [
      ['findings', compiled.findings.map((finding) => finding.id)],
      ['candidateEvaluations', compiled.candidateEvaluations.map((entry) => entry.candidateId)],
      ['projections', compiled.projections.map((projection) => projection.id)],
    ] as const) {
      if (new Set(ids).size !== ids.length) {
        context.addIssue({
          code: z.ZodIssueCode.custom,
          path: [path],
          message: `Compiled shared-finding ${path} IDs must be unique.`,
        });
      }
    }
    const definitionIds = compiled.findings.map((finding) => finding.definitionId);
    if (new Set(definitionIds).size !== definitionIds.length) {
      context.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['findings'],
        message: 'A compiled shared-finding set may resolve each definition only once.',
      });
    }
    const contributionIds = compiled.findings.flatMap((finding) =>
      finding.contributions.map((contribution) => contribution.id),
    );
    if (new Set(contributionIds).size !== contributionIds.length) {
      context.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['findings'],
        message: 'Compiled finding contribution IDs must be globally unique.',
      });
    }
    const evaluatedContributionIds = compiled.candidateEvaluations.flatMap(
      (evaluation) => evaluation.contributionIds,
    );
    if (
      new Set(evaluatedContributionIds).size !== evaluatedContributionIds.length ||
      [...contributionIds].sort().join('\u0000') !==
        [...evaluatedContributionIds].sort().join('\u0000')
    ) {
      context.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['candidateEvaluations'],
        message: 'Candidate evaluations must partition exactly the compiled finding contributions.',
      });
    }
    const findingsByDefinition = new Map(
      compiled.findings.map((finding) => [finding.definitionId, finding]),
    );
    for (const [index, finding] of compiled.findings.entries()) {
      if (
        finding.resolution.origin !== 'compiled' ||
        finding.resolution.resolverVersion !== compiled.compilerVersion
      ) {
        context.addIssue({
          code: z.ZodIssueCode.custom,
          path: ['findings', index, 'resolution'],
          message: 'Every compiled finding must retain this compiler version and compiled origin.',
        });
      }
      if (
        !compiled.candidateEvaluations.some(
          (evaluation) => evaluation.findingDefinitionId === finding.definitionId,
        )
      ) {
        context.addIssue({
          code: z.ZodIssueCode.custom,
          path: ['findings', index],
          message: 'Every resolved finding requires at least one candidate evaluation.',
        });
      }
    }
    for (const [index, evaluation] of compiled.candidateEvaluations.entries()) {
      const finding = findingsByDefinition.get(evaluation.findingDefinitionId);
      if (
        !finding ||
        evaluation.contributionIds.some(
          (contributionId) =>
            !finding.contributions.some((contribution) => contribution.id === contributionId),
        )
      ) {
        context.addIssue({
          code: z.ZodIssueCode.custom,
          path: ['candidateEvaluations', index],
          message: 'A candidate evaluation must reference contributions on its resolved finding.',
        });
      }
      const shouldBeApplied = evaluation.disposition === 'applied';
      for (const contributionId of evaluation.contributionIds) {
        if (
          finding &&
          finding.resolution.appliedContributionIds.includes(contributionId) !== shouldBeApplied
        ) {
          context.addIssue({
            code: z.ZodIssueCode.custom,
            path: ['candidateEvaluations', index, 'disposition'],
            message: 'Candidate disposition must agree with applied contribution IDs.',
          });
        }
      }
    }
    const projectionDefinitionIds = compiled.projections.map(
      (projection) => projection.projectionId,
    );
    if (new Set(projectionDefinitionIds).size !== projectionDefinitionIds.length) {
      context.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['projections'],
        message: 'A compiled set may resolve each reveal projection at most once.',
      });
    }
    const resolvedFindingIds = new Set(compiled.findings.map((finding) => finding.id));
    for (const [index, projection] of compiled.projections.entries()) {
      if (
        projection.resolution.compilerVersion !== compiled.compilerVersion ||
        projection.resolution.inputFingerprint !== compiled.inputFingerprint
      ) {
        context.addIssue({
          code: z.ZodIssueCode.custom,
          path: ['projections', index, 'resolution'],
          message:
            'Every compiled projection must retain this compiler version and input fingerprint.',
        });
      }
      if (
        (projection.selectedExpression === null) !==
        (projection.resolution.stableDrawId === null)
      ) {
        context.addIssue({
          code: z.ZodIssueCode.custom,
          path: ['projections', index, 'resolution', 'stableDrawId'],
          message:
            'A compiled projection has a stable wording draw exactly when it selected expression text.',
        });
      }
      if (
        projection.contributingResolvedFindingIds.some(
          (findingId) => !resolvedFindingIds.has(findingId),
        )
      ) {
        context.addIssue({
          code: z.ZodIssueCode.custom,
          path: ['projections', index, 'contributingResolvedFindingIds'],
          message: 'A compiled projection may reference only findings in the same compiled set.',
        });
      }
    }
  });
export type CompiledSharedFindingSet = z.infer<typeof CompiledSharedFindingSetSchema>;

export const MeasurementDefinitionSchema = z
  .object({
    schemaVersion: SchemaVersionSchema,
    contentVersion: ContentVersionSchema,
    id: StableIdSchema,
    label: z.string().trim().min(1).max(160),
    domain: z.enum(['vital_sign', 'anthropometric', 'physical_exam_measurement']),
    unit: z
      .object({
        display: z.string().trim().min(1).max(40),
        ucumCode: z.string().trim().min(1).max(40),
        displayPrecision: z.number().int().min(0).max(6),
      })
      .strict(),
    availableThroughActionIds: z.array(StableIdSchema),
    allowedContextDimensionIds: z.array(StableIdSchema),
    lifecycle: ContentLifecycleSchema,
    medicalReviewStatus: MedicalReviewStatusSchema,
  })
  .strict()
  .superRefine((definition, context) => {
    for (const [path, ids] of [
      ['availableThroughActionIds', definition.availableThroughActionIds],
      ['allowedContextDimensionIds', definition.allowedContextDimensionIds],
    ] as const) {
      if (new Set(ids).size !== ids.length) {
        context.addIssue({
          code: z.ZodIssueCode.custom,
          path: [path],
          message: 'Measurement definition references must be unique.',
        });
      }
    }
  });
export type MeasurementDefinition = z.infer<typeof MeasurementDefinitionSchema>;

